PRAGMA foreign_keys = ON;

-- BOS_CYO 2026-09-14: replace the Dermo Product Master photos for the exact
-- name-based Leker set approved from Google Drive: akuntan rika / variant leker.
-- Scope is store_dermo and products.image_data only. The three explicit skips
-- (Adonan Leker, Leker Blueberry + Gula, and Leker Original) stay untouched.
-- Images are mobile-ready 192x192 WebP. Each source row is its own small D1
-- statement so the largest statement remains around 8 KB, far below 100 KB.
-- Strawberry + Gula uses the healthy same-account Drive WebP counterpart because
-- its PNG in variant leker is corrupt; the approved product-to-asset mapping is
-- unchanged.
-- DOC-IMPACT: NOT_REQUIRED — this follows the existing Product Master v5
-- image_data contract; no schema, API, event, or runtime contract changes.

CREATE TABLE dermo_leker_photo_source_0093 (
  product_name TEXT PRIMARY KEY,
  drive_asset_name TEXT NOT NULL UNIQUE,
  image_data TEXT NOT NULL CHECK (image_data LIKE 'data:image/webp;base64,%')
);








































































-- Fail closed unless the complete current Dermo name-based Leker set is exactly
-- the approved 71 replacements plus the three explicit skips.
CREATE TABLE dermo_leker_photo_guard_0093 (ok INTEGER NOT NULL CHECK (ok = 1));
SELECT CASE WHEN
  EXISTS (SELECT 1 FROM stores WHERE id = 'store_dermo')
  AND (SELECT COUNT(*) FROM dermo_leker_photo_source_0093) = 71
  AND NOT EXISTS (
    SELECT 1 FROM dermo_leker_photo_source_0093
    WHERE LOWER(product_name) NOT LIKE '%leker%'
  )
  AND (
    SELECT COUNT(*) FROM products
    WHERE store_id = 'store_dermo' AND LOWER(name) LIKE '%leker%'
  ) = 74
  AND (
    SELECT COUNT(*)
    FROM products p
    JOIN dermo_leker_photo_source_0093 s ON s.product_name = p.name
    WHERE p.store_id = 'store_dermo' AND LOWER(p.name) LIKE '%leker%'
  ) = 71
  AND (
    SELECT COUNT(*)
    FROM products p
    WHERE p.store_id = 'store_dermo'
      AND LOWER(p.name) LIKE '%leker%'
      AND NOT EXISTS (
        SELECT 1 FROM dermo_leker_photo_source_0093 s
        WHERE s.product_name = p.name
      )
  ) = 3
  AND (
    SELECT COUNT(*)
    FROM products p
    WHERE p.store_id = 'store_dermo'
      AND LOWER(p.name) LIKE '%leker%'
      AND NOT EXISTS (
        SELECT 1 FROM dermo_leker_photo_source_0093 s
        WHERE s.product_name = p.name
      )
      AND p.name IN ('Adonan Leker', 'Leker Blueberry + Gula', 'Leker Original')
  ) = 3
THEN 1 ELSE 0 END;
DROP TABLE dermo_leker_photo_guard_0093;

UPDATE products
SET image_data = (
  SELECT s.image_data
  FROM dermo_leker_photo_source_0093 s
  WHERE s.product_name = products.name
)
WHERE store_id = 'store_dermo'
  AND LOWER(name) LIKE '%leker%'
  AND EXISTS (
    SELECT 1 FROM dermo_leker_photo_source_0093 s
    WHERE s.product_name = products.name
  );

CREATE TABLE dermo_leker_photo_verify_0093 (ok INTEGER NOT NULL CHECK (ok = 1));
SELECT CASE WHEN (
  SELECT COUNT(*)
  FROM products p
  JOIN dermo_leker_photo_source_0093 s
    ON s.product_name = p.name AND s.image_data = p.image_data
  WHERE p.store_id = 'store_dermo' AND LOWER(p.name) LIKE '%leker%'
) = 71 THEN 1 ELSE 0 END;
DROP TABLE dermo_leker_photo_verify_0093;
DROP TABLE dermo_leker_photo_source_0093;
